<script setup lang="ts">import {ref,onMounted,onUnmounted} from 'vue';import {useRoute} from '../hooks/useRoute';import {useSource} from '../stores/source';import {useResearch} from '../stores/research';import Frame from '../components/Frame.vue';import Notice from '../components/common/Notice.vue';import Overview from '../pages/Overview.vue';import Source from '../pages/Source.vue';import Config from '../pages/Config.vue';import Results from '../pages/Results.vue';import Memos from '../pages/Memos.vue';import Audit from '../pages/Audit.vue';defineProps<{user:any}>();defineEmits(['logout']);const route=useRoute(),source=useSource(),research=useResearch(),selectedId=ref(0);let timer:ReturnType<typeof setInterval>;onMounted(()=>{source.reload();research.reload();timer=setInterval(research.reload,3000)});onUnmounted(()=>clearInterval(timer));function open(run:any){selectedId.value=run.id;location.hash='results'}</script><template><Frame :route="route" :user="user" @logout="$emit('logout')"><Notice :error="source.state.error||research.state.error"/><Source v-if="route==='source'" v-bind="source.state" :user="user" :reload-source="source.reload"/><Config v-else-if="route==='config'" v-bind="source.state" :runs="research.state.runs" :user="user" :reload-research="research.reload" @open="open"/><Results v-else-if="route==='results'" :runs="research.state.runs" :selected-id="selectedId" :user="user" :reload-research="research.reload" @open="open"/><Memos v-else-if="route==='memos'" v-bind="research.state" :user="user" :reload-research="research.reload"/><Audit v-else-if="route==='audit'"/><Overview v-else v-bind="source.state" :runs="research.state.runs" :memos="research.state.memos" @open="open"/></Frame></template>
